  (12982, 1169, 6, '九成新画架', '临近考试季急售，画架，支架稳固，可调高度，适合美术作业。，价格可议，诚心要的来。', 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1460661419201-fd4cecdf8a8b?auto=format&fit=crop&w=800&q=80', '103.00', 1, '学生活动中心', '学生活动中心一楼', '22.503000', '113.903000', 56, 1, 1, 1, '2026-05-26 08:18:00'),
  (12983, 1183, 7, '功能正常跑步鞋', '鞋底缓震良好，适合操场跑步和健身。 因课程结束或宿舍整理转让，支持当面查看实物。', 'https://images.unsplash.com/photo-1460353581641-37baddab0fa2?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1551107696-a4b0c5a0d9a2?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=800&q=80', '295.00', 2, '校园南门', '校园南门保安亭旁', '22.510000', '113.910000', 75, 2, 1, 1, '2026-05-26 08:55:00'),
  (12984, 1197, 8, '毕业转让眼影盘', '毕业季清仓，眼影盘，配色日常实用，粉质细腻，使用次数少。，有意者速联，可小刀。', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', '130.00', 3, '三号宿舍区门口', '三号宿舍区入口处', '22.502000', '113.902000', 94, 4, 1, 1, '2026-05-26 09:32:00'),
  (12985, 1212, 9, '自用闲置蛋白棒', '有轻微使用痕迹，功能完全正常，健身代餐蛋白棒，多口味，保质期充裕。，可验货后付款。', 'https://images.unsplash.com/photo-1599599810694-b5b37304c041?auto=format&fit=crop&w=800&q=80', '77.00', 1, '二号宿舍区门口', '二号宿舍区入口处', '22.509000', '113.909000', 113, 3, 1, 4, '2026-05-26 10:09:00'),
  (12986, 1227, 10, '几乎全新耳放', '朋友赠送，个人用不上，耳放全新未拆封，原价购入，亏本转让。', 'https://images.unsplash.com/photo-1484704849700-f032a568e944?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1558089687-f282ffcbc126?auto=format&fit=crop&w=800&q=80', '346.00', 2, '第一教学楼大厅', '第一教学楼一楼大厅', '22.501000', '113.901000', 132, 0, 1, 1, '2026-05-26 10:46:00'),
  (12987, 1241, 11, '八成新小型绿植', '临近考试季急售，小型绿植，桌面绿植盆栽，附花盆，适合宿舍摆放。，价格可议，诚心要的来。', 'https://images.unsplash.com/photo-1459411552884-841db9b3cc2a?auto=format&fit=crop&w=800&q=80,https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=800&q=80', '53.00', 3, '创新中心大厅', '创新中心一楼大厅', '22.508000', '113.908000', 151, 3, 1, 1, '2026-05-26 11:23:00'),
  (12988, 1256, 12, '九成新音乐节门票', '周末音乐节门票，因行程冲突低价转让。 因课程结束或宿舍整理转让，支持当面查看实物。', 'https://images.unsplash.com/photo-1459749411175-04bf5292ceea?auto=format&fit=crop&w=800&q=80', '330.00', 1, '图书馆北门', '校园图书馆北门入口', '22.500000', '113.900000', 170, 3, 1, 1, '2026-05-26 12:00:00')
