VALUES
  (1, '1_2_3', 1, 3, 2, '你好，键盘还在吗？', 'text', '2026-05-25 09:02:00'),
  (2, '1_2_3', 1, 2, 3, '还在，图书馆北门交易可以吗？', 'text', '2026-05-25 09:06:00'),
